<template><section class="cc-page"><div class="cc-heading"><div><span class="cc-eyebrow">巡护指挥台 / 视频工作区</span><h1>视频监控</h1><p>自由安排观看窗口；高清名额由服务端统一分配。</p></div><button class="cc-button" :disabled="loading" @click="refresh"><ReloadOutlined />刷新设备</button></div><div v-if="error" class="cc-error" role="alert">{{ error }}</div><div v-if="bandwidthError" class="cc-error" role="alert">视频档位暂时无法确认，画面播放不代表已取得高清名额。</div><div class="cc-toolbar"><div style="display:flex;gap:10px"><button class="cc-button" :disabled="!windows.length" @click="tile">一键平铺</button><button class="cc-button" :disabled="!windows.length" @click="maximize=undefined">还原窗口</button></div><span class="cc-muted">已打开 {{ windows.length }} 路 · 高清上传 {{ bandwidthError?'—':highCount }} 路 / 上限 4</span></div><div class="cc-video-workspace"><div ref="stage" class="cc-video-stage" @dragover.prevent @drop.prevent="drop"><div v-if="!windows.length" class="cc-stage-empty"><VideoCameraOutlined /><h2>选择需要关注的飞机</h2><p>点击右侧设备或拖入此处，添加观看窗口。</p></div><article v-for="win in windows" :key="win.id" class="cc-video-window" :style="windowStyle(win)"><header @pointerdown="startMove($event,win,'move')" @keydown="moveKeyboard($event,win)" tabindex="0" :aria-label="`移动 ${deviceName(win.id)} 窗口`"><span>{{ deviceName(win.id) }}</span><div @pointerdown.stop><button :aria-label="`操作 ${deviceName(win.id)}`" @click="openControls(win.id)">操作</button><button :aria-label="`放大 ${deviceName(win.id)}`" @click="maximize=maximize===win.id?undefined:win.id"><ExpandOutlined /></button><button :aria-label="`关闭 ${deviceName(win.id)}`" @click="close(win.id)"><CloseOutlined /></button></div></header><div class="cc-video-content"><div v-if="groups[win.id]?.statusMessage === '播放信息读取失败'" class="cc-empty" role="alert">播放信息读取失败<button class="cc-text-button" @click="refreshStreams">重试</button></div><LiveVideo v-else :url="playUrl(win.id)" /></div><footer><span>{{ profile(win.id) }}</span><button class="cc-text-button" @click="toggleHigh(win.id)">{{ highRequested.has(win.id)?'释放高清关注':'申请高清关注' }}</button></footer><button class="cc-window-resize" :aria-label="`调整 ${deviceName(win.id)} 窗口大小`" @pointerdown.stop="startMove($event,win,'resize')" @keydown="resizeKeyboard($event,win)"><ArrowsAltOutlined /></button></article></div><aside class="cc-panel cc-video-devices"><h2>巡查飞机 <small>{{ devices.length }}</small></h2><label class="cc-search"><SearchOutlined /><input v-model="search" aria-label="搜索视频设备" placeholder="搜索名称或编号" /></label><div v-if="!devices.length" class="cc-empty">{{ loading?'正在读取设备…':'暂无已接入巡护飞机' }}</div><button v-for="device in visibleDevices" :key="device.aircraftSn" class="cc-device-tile" draggable="true" @dragstart="$event.dataTransfer.setData('text/plain',device.aircraftSn)" @click="add(device.aircraftSn)"><VideoCameraOutlined /><div><strong>{{ device.deviceName||device.aircraftSn }}</strong><p>{{ device.model||device.aircraftModelKey||'机型未上报' }}</p><small>{{ device.online?'在线':'离线' }} · {{ device.batteryPercent==null?'电量未知':device.batteryPercent+'%' }}</small></div><span class="cc-status" :class="device.online?'info':'neutral'">{{ windows.some(w=>w.id===device.aircraftSn)?'已打开':'添加' }}</span></button><p class="cc-muted">关闭窗口仅结束本地观看，不会停止飞机上传。</p></aside></div><DeviceOperations id="cc-device-operations" v-if="controlSn" :key="controlSn" :device="controlDevice" @close="controlSn=undefined" /></section></template>
<script setup lang="ts">
import { ref, reactive, computed, watch, nextTick, onMounted, onBeforeUnmount } from 'vue'
import { useRoute } from 'vue-router'
import { ReloadOutlined, VideoCameraOutlined, ExpandOutlined, CloseOutlined, SearchOutlined, ArrowsAltOutlined } from '@ant-design/icons-vue'
import { listMsdkDevices, MsdkDeviceState } from '/@/api/msdk-device'
import { getDualStreamGroup, DualStreamGroup } from '/@/api/manage'
import { getVideoBandwidthStatus, updateVideoViewer } from '/@/api/video-bandwidth'
import { createVideoViewerLease, videoProfileLabel } from '/@/components/cockpit/video-bandwidth-runtime.mjs'
import DeviceOperations from '/@/components/command-center/DeviceOperations.vue'
import LiveVideo from '/@/components/command-center/LiveVideo.vue'
import { tileWindows, boundWindow, restoreWindows } from '/@/components/command-center/video-layout.mjs'
import { ELocalStorageKey } from '/@/types'
import { uuidv4 } from '/@/utils/uuid'
const route = useRoute(); const devices = ref<MsdkDeviceState[]>([]); const windows = ref<any[]>([]); const groups = reactive<Record<string, DualStreamGroup>>({}); const rows = ref<any[]>([]); const stage = ref<HTMLElement|null>(null); const search = ref(''); const error = ref(''); const loading = ref(false); const bandwidthError = ref(false); const maximize = ref<string>(); const highRequested = reactive(new Set<string>())
const controlSn = ref<string>()
const controlDevice = computed(() => devices.value.find(d => d.aircraftSn === controlSn.value) || null)
const visibleDevices = computed(() => devices.value.filter(d => `${d.deviceName || ''} ${d.aircraftSn}`.toLowerCase().includes(search.value.toLowerCase())))
const highCount = computed(() => rows.value.filter(r => r.online && r.agent?.applied_profile === 'HIGH').length)
const storageKey = `uavfire.command.video.v1.${localStorage.getItem(ELocalStorageKey.WorkspaceId) || 'none'}`
const leases = new Map<string, any>(); const viewerId = uuidv4()
let initialized = false; let disposed = false; let polling = false; let timer:ReturnType<typeof setInterval>; let cleanupPointer:(()=>void)|undefined
const deviceName = (sn:string) => devices.value.find(d => d.aircraftSn === sn)?.deviceName || sn
const playUrl = (sn:string) => devices.value.find(d => d.aircraftSn === sn)?.online ? groups[sn]?.visiblePlayUrl : undefined
const profile = (sn:string) => bandwidthError.value ? '档位待确认' : videoProfileLabel(rows.value.find(r => r.drone_sn === sn))
function windowStyle (w:any) { if (maximize.value) return maximize.value === w.id ? { left: '0', top: '0', width: '100%', height: '100%', zIndex: 100 } : { visibility: 'hidden' }; return { left: w.x * 100 + '%', top: w.y * 100 + '%', width: w.width * 100 + '%', height: w.height * 100 + '%', zIndex: w.z } }
function add (sn:string) { if (!devices.value.some(d => d.aircraftSn === sn)) return; if (!windows.value.some(w => w.id === sn)) { windows.value = tileWindows([...windows.value, { id: sn, z: windows.value.length + 1 }]); maximize.value = undefined; refreshStreams() } else maximize.value = sn }
function drop (event:DragEvent) { add(event.dataTransfer?.getData('text/plain') || '') }
function tile () { windows.value = tileWindows(windows.value); maximize.value = undefined }
async function openControls (sn:string) { controlSn.value = sn; await nextTick(); document.getElementById('cc-device-operations')?.scrollIntoView({ behavior: 'smooth', block: 'nearest' }) }
function close (sn:string) { if (controlSn.value === sn) controlSn.value = undefined; leases.get(sn)?.stop(); leases.delete(sn); highRequested.delete(sn); windows.value = windows.value.filter(w => w.id !== sn); delete groups[sn]; if (maximize.value === sn)maximize.value = undefined }
function toggleHigh (sn:string) { if (highRequested.has(sn)) { leases.get(sn)?.stop(); leases.delete(sn); highRequested.delete(sn) } else { const lease = createVideoViewerLease({ send: (target:string|null) => updateVideoViewer(`${viewerId}-${sn}`, target), onError: () => { if (!disposed)bandwidthError.value = true } }); leases.set(sn, lease); highRequested.add(sn); lease.select(document.hidden ? null : sn) } }
async function refreshStreams () { if (polling || disposed) return; polling = true; const sns = windows.value.map(w => w.id); await Promise.allSettled(sns.map(async sn => { try { const response = await getDualStreamGroup(sn); if (response.code !== 0) throw new Error(); if (!disposed && windows.value.some(w => w.id === sn))groups[sn] = response.data } catch (_) { if (!disposed && windows.value.some(w => w.id === sn))groups[sn] = { droneSn: sn, statusMessage: '播放信息读取失败' } } })); try { const status = await getVideoBandwidthStatus(); if (!disposed) { rows.value = status?.aircraft || []; bandwidthError.value = false } } catch (_) { if (!disposed)bandwidthError.value = true } finally { polling = false } }
async function refresh () { if (loading.value || disposed) return; loading.value = true; try { const r = await listMsdkDevices(true); if (r.code !== 0) throw new Error(); if (disposed) return; devices.value = r.data; error.value = ''; if (!initialized) { initialized = true; try { windows.value = restoreWindows(JSON.parse(localStorage.getItem(storageKey) || 'null'), r.data.map(d => d.aircraftSn)) } catch (_) {} if (typeof route.query.sn === 'string')add(route.query.sn); if (!windows.value.length && !localStorage.getItem(storageKey))windows.value = tileWindows(r.data.filter(d => d.online).slice(0, 4).map(d => ({ id: d.aircraftSn }))) } await refreshStreams() } catch (_) { if (!disposed)error.value = '设备列表更新失败，请检查服务后重试。' } finally { loading.value = false } }
function startMove (event:PointerEvent, w:any, mode:string) { if (event.button !== 0 || maximize.value) return; event.preventDefault(); cleanupPointer?.(); const bounds = stage.value?.getBoundingClientRect(); if (!bounds) return; const start = { ...w }; const x = event.clientX; const y = event.clientY; w.z = Math.max(...windows.value.map(item => item.z), 0) + 1; const move = (e:PointerEvent) => { const dx = (e.clientX - x) / bounds.width; const dy = (e.clientY - y) / bounds.height; Object.assign(w, boundWindow(mode === 'move' ? { ...w, x: start.x + dx, y: start.y + dy } : { ...w, width: start.width + dx, height: start.height + dy })) }; const end = () => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', end); window.removeEventListener('pointercancel', end); cleanupPointer = undefined }; cleanupPointer = end; window.addEventListener('pointermove', move); window.addEventListener('pointerup', end); window.addEventListener('pointercancel', end) }
function moveKeyboard (e:KeyboardEvent, w:any) { const dirs = { ArrowLeft: [-0.02, 0], ArrowRight: [0.02, 0], ArrowUp: [0, -0.02], ArrowDown: [0, 0.02] }; const d = dirs[e.key]; if (d) { e.preventDefault(); Object.assign(w, boundWindow({ ...w, x: w.x + d[0], y: w.y + d[1] })) } }
function resizeKeyboard (e:KeyboardEvent, w:any) { const dirs = { ArrowLeft: [-0.02, 0], ArrowRight: [0.02, 0], ArrowUp: [0, -0.02], ArrowDown: [0, 0.02] }; const d = dirs[e.key]; if (d) { e.preventDefault(); Object.assign(w, boundWindow({ ...w, width: w.width + d[0], height: w.height + d[1] })) } }
function visibility () { leases.forEach((lease, sn) => lease.select(document.hidden ? null : sn)); if (!document.hidden)refresh() }
watch(windows, value => { if (initialized) try { localStorage.setItem(storageKey, JSON.stringify(value)) } catch (_) {} }, { deep: true })
watch(() => route.query.sn, value => { if (typeof value === 'string')add(value) })
onMounted(() => { refresh(); timer = setInterval(() => { if (!document.hidden)refresh() }, 10000); document.addEventListener('visibilitychange', visibility) })
onBeforeUnmount(() => { disposed = true; clearInterval(timer); cleanupPointer?.(); leases.forEach(lease => lease.stop()); document.removeEventListener('visibilitychange', visibility) })
</script>
<style scoped>
.cc-video-workspace{display:grid;grid-template-columns:minmax(0,1fr) 275px;gap:18px}.cc-video-stage{height:calc(100dvh - 310px);min-height:480px;position:relative;background:#080f19;border:1px solid #26364a;border-radius:7px;overflow:hidden}.cc-stage-empty{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12px;color:#8199b8;padding:25px;text-align:center}.cc-stage-empty>.anticon{font-size:38px}.cc-stage-empty p{margin:0}.cc-video-window{position:absolute;display:flex;flex-direction:column;background:#122034;border:1px solid #42618a;border-radius:6px;overflow:hidden;min-width:0}.cc-video-window header{height:36px;flex-shrink:0;display:flex;align-items:center;justify-content:space-between;padding:0 10px;gap:10px;cursor:move;touch-action:none;background:#1c2e46;font-size:12px}.cc-video-window header>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.cc-video-window header div{display:flex;gap:9px}.cc-video-window header button{border:0;background:transparent;color:#a5bfdf;cursor:pointer;padding:3px}.cc-video-content{flex:1;min-height:0}.cc-video-window footer{height:34px;padding:0 28px 0 10px;display:flex;align-items:center;justify-content:space-between;gap:7px;font-size:10px}.cc-video-window footer span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.cc-window-resize{position:absolute;bottom:1px;right:1px;border:0;background:#203a58;color:#91b4e4;cursor:nwse-resize;touch-action:none}.cc-video-devices{padding:18px;max-height:calc(100dvh - 310px);min-height:480px;overflow:auto}.cc-video-devices h2{display:flex;justify-content:space-between;margin-bottom:15px}.cc-video-devices small{color:#8098b7}.cc-video-devices .cc-search input{width:100%}.cc-device-tile{width:100%;background:#18283e;border:1px solid #30445f;border-radius:6px;display:flex;gap:12px;padding:14px 10px;align-items:center;color:#b6cbea;text-align:left;margin-top:12px;cursor:pointer}.cc-device-tile>div{flex:1;min-width:0}.cc-device-tile strong{font-size:12px;display:block;overflow-wrap:anywhere}.cc-device-tile p{font-size:11px;color:#899fbc;margin:5px 0}.cc-video-devices>p{font-size:11px;margin:18px 0}
@media(max-width:900px){.cc-video-workspace{grid-template-columns:minmax(0,1fr) 220px}.cc-video-devices{padding:12px}}@media(max-width:650px){.cc-video-workspace{display:flex;flex-direction:column}.cc-video-stage{height:480px;min-height:480px}.cc-video-devices{max-height:400px;min-height:0}.cc-video-window footer{height:auto;min-height:34px;flex-wrap:wrap}.cc-video-window header{font-size:10px}.cc-video-window footer .cc-text-button{font-size:9px}}
</style>
